<?php
require_once '../config.php'; require_admin(); $pageTitle='Manage motorcycles'; $message='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='delete'){$st=$pdo->prepare("DELETE FROM motorcycles WHERE id=?");$st->execute([(int)$_POST['id']]);$message='Motorcycle deleted.';}
 elseif($action==='save'){$id=(int)($_POST['id']??0);$data=[trim($_POST['name']),trim($_POST['category']),trim($_POST['transmission']),(float)$_POST['price_per_day'],trim($_POST['description']),trim($_POST['image']),$_POST['availability']];if($id){$st=$pdo->prepare("UPDATE motorcycles SET name=?,category=?,transmission=?,price_per_day=?,description=?,image=?,availability=? WHERE id=?");$st->execute([...$data,$id]);}else{$st=$pdo->prepare("INSERT INTO motorcycles(name,category,transmission,price_per_day,description,image,availability) VALUES(?,?,?,?,?,?,?)");$st->execute($data);}$message='Motorcycle saved.';}
}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare("SELECT * FROM motorcycles WHERE id=?");$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}
$rows=$pdo->query("SELECT * FROM motorcycles ORDER BY id DESC")->fetchAll();require '../includes/header.php'; ?>
<section class="page-banner"><div class="container"><div class="eyebrow">ADMIN</div><h1>Manage motorcycles</h1></div></section><div class="container-fluid"><div class="row"><aside class="col-md-2 admin-sidebar"><a href="dashboard.php">Dashboard</a><a href="motorcycles.php">Motorcycles</a><a href="bookings.php">Bookings</a><a href="customers.php">Customers</a><a href="logout.php">Logout</a></aside><div class="col-md-10 p-4"><?php if($message): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><div class="content-card mb-4"><h4><?= $edit?'Edit':'Add' ?> motorcycle</h4><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="col-md-4"><label class="form-label">Motorcycle name</label><input class="form-control" name="name" required value="<?= e($edit['name']??'') ?>"></div><div class="col-md-3"><label class="form-label">Category</label><input class="form-control" name="category" required value="<?= e($edit['category']??'Scooter') ?>"></div><div class="col-md-2"><label class="form-label">Transmission</label><input class="form-control" name="transmission" value="<?= e($edit['transmission']??'Automatic') ?>"></div><div class="col-md-3"><label class="form-label">Price per day (₱)</label><input type="number" step=".01" min="0" class="form-control" name="price_per_day" required value="<?= e($edit['price_per_day']??'500') ?>"></div><div class="col-md-6"><label class="form-label">Image path or URL</label><input class="form-control" name="image" value="<?= e($edit['image']??'') ?>" placeholder="assets/images/your-bike.jpg"></div><div class="col-md-3"><label class="form-label">Availability</label><select class="form-select" name="availability"><option <?= ($edit['availability']??'available')==='available'?'selected':'' ?>>available</option><option <?= ($edit['availability']??'')==='unavailable'?'selected':'' ?>>unavailable</option></select></div><div class="col-md-12"><label class="form-label">Description</label><textarea class="form-control" name="description"><?= e($edit['description']??'') ?></textarea></div><div class="col-12"><button class="btn btn-yellow">Save motorcycle</button> <?php if($edit): ?><a class="btn btn-outline-secondary" href="motorcycles.php">Cancel</a><?php endif; ?></div></form></div><div class="content-card"><h4>Motorcycle list</h4><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Name</th><th>Category</th><th>Rate/day</th><th>Availability</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['category']) ?></td><td>₱<?= number_format((float)$r['price_per_day'],2) ?></td><td><?= e($r['availability']) ?></td><td><a class="btn btn-sm btn-dark" href="?edit=<?= (int)$r['id'] ?>">Edit</a> <form method="post" class="d-inline" onsubmit="return confirm('Delete this motorcycle?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></div>
